export function createHostRunHandlers(ctx: HandlerContext, options: CreateHostRunHandlersOptions = {}) {
  return {
    async host_run(args: HostRunCommandArgs): Promise<HostRunCommandResult | HostRunDetachResult | string> {
      const host = normalizeHost(normalizeString(args.host));
      const agentType = normalizeString(args.agentType);
      if (!agentType) throw new Error('host_run: --agentType is required');
      const timeoutMs = optionalPositiveInteger('host_run', 'timeoutMs', args.timeoutMs);
      const deadlineMs = optionalPositiveInteger('host_run', 'deadlineMs', args.deadlineMs);
      const storyId = normalizeString(args.storyId) || null;
      const reviewRunId = normalizeString(args.reviewRunId) || null;
      const lane = normalizeString(args.lane) || null;

      // Exactly one of --prompt / --promptFile.
      const hasPrompt = typeof args.prompt === 'string' && args.prompt.length > 0;
      const promptFilePath = normalizeString(args.promptFile);
      const hasPromptFile = promptFilePath.length > 0;
      let promptText: string;
      let formalReviewBinding: {
        headHash: string;
        materialHash: string;
        storyFilesHash: string;
        promptHash: string;
        envelopeId: string | null;
      } | null = null;
      if (args.managedReview === true) {
        if (hasPrompt || hasPromptFile) {
          throw new Error('host_run: --managedReview derives the exact prompt from ReviewRun; do not pass --prompt or --promptFile');
        }
        if (!storyId || !reviewRunId || !lane || agentType !== lane) {
          throw new Error('host_run: --managedReview requires storyId, reviewRunId, lane, and agentType equal to that lane');
        }
        const story = ctx.store.readStory(storyId);
        const reviewRun = assertCurrentReviewRunForEvidence(ctx.store, story, ctx.root, lane, reviewRunId);
        const storyFilesHash = reviewRun.storyFilesHash ?? reviewRun.workspaceBinding?.storyFilesHash ?? '';
        if (!storyFilesHash) throw new Error('host_run: --managedReview requires a ReviewRun with storyFilesHash binding');
        promptText = buildManagedReviewerPrompt(reviewRun.workspaceBinding?.metadataRoot ?? ctx.root, reviewRun);
        formalReviewBinding = {
          headHash: reviewRun.headHash,
          materialHash: reviewRun.materialHash,
          storyFilesHash,
          promptHash: reviewRun.promptHash,
          envelopeId: reviewRun.envelopeId ?? null,
        };
      } else if (hasPrompt === hasPromptFile) {
        throw new Error('host_run: provide exactly one of --prompt or --promptFile (or use --managedReview with an exact ReviewRun)');
      } else if (hasPromptFile) {
        try {
          promptText = readFileSync(promptFilePath, 'utf8');
        } catch (err) {
          throw new Error(`host_run: cannot read --promptFile "${promptFilePath}": ${err instanceof Error ? err.message : String(err)}`);
        }
      } else {
        promptText = args.prompt as string;
      }
      if (promptText.length === 0) {
        throw new Error('host_run: prompt is empty; refuse pre-spawn');
      }

      // Defense in depth (core enforces this too): a reviewRunId must belong to
      // --storyId so a ledger row cannot silently mis-join across stories.
      if (reviewRunId && storyId && !reviewRunId.startsWith(`${storyId}:`)) {
        throw new Error(
          `host_run: reviewRunId "${reviewRunId}" does not belong to story "${storyId}" ` +
          `(a reviewRunId must be "<storyId>:..."); refuse pre-spawn`,
        );
      }
      const json = wantsJson(args);

      // F-005: resolve story phase + existence through the CONFIGURED store, so a
      // project that configures storyDir is honored (the core stays path-free). An
      // explicit --phase never reaches this (the core skips the store entirely).
      const resolveStory: HostRunStoryResolver = (id: string) => {
        try {
          const story = ctx.store.readStory(id);
          const p = typeof story.phase === 'string' && story.phase.length > 0 ? story.phase : null;
          return { phase: p };
        } catch {
          return null; // unknown story per the configured store
        }
      };

      const explicitPhase = normalizeString(args.phase);
      let phase = explicitPhase || 'adhoc';
      if (!explicitPhase && storyId) {
        const story = resolveStory(storyId);
        if (!story) throw new Error(`host_run: unknown story "${storyId}"; refuse pre-spawn`);
        phase = story.phase || 'adhoc';
      }
      const injectedLauncher: ManagedHostRunWorkerLauncher | undefined = options.runner
        ? async request => {
          void runManagedHostRunWorker(request, { runner: options.runner, env: process.env })
            .catch(() => { /* worker persists its own terminal error where possible */ });
          return { pid: process.pid };
        }
        : undefined;
      const submitted = await submitManagedHostRun(
        {
          host,
          storyId,
          agentType,
          phase,
          promptText,
          reviewRunId,
          lane,
          timeoutMs,
          deadlineMs: deadlineMs ?? timeoutMs,
          cwd: ctx.root,
          root: ctx.root,
          projectRootHash: projectRootHashFor(ctx.root),
          ...(formalReviewBinding ? { profile: 'managed_reviewer', reviewBinding: formalReviewBinding } : {}),
        },
        { launchWorker: options.launchWorker ?? injectedLauncher },
      );
      // Publish the durable identity before either detach returns or foreground
      // attach begins. If the caller disappears while attached, a replacement
      // controller can recover the same worker-owned run through host_run_status
      // instead of launching a duplicate provider.
      ctx.log?.(
        `[host_run] submitted runId=${submitted.runId} state=${submitted.state} `
        + `deadlineAt=${submitted.deadlineAt} attach=${args.detach === true ? 'detached' : 'foreground'}`,
      );
      if (args.detach === true) {
        return { schemaVersion: 'lattice.host_run.v2', detached: true, run: submitted };
      }

      // F-006 / F-008 / F-020: live passthrough. text mode routes host
      // stdout->stdout / stderr->stderr; json mode routes EVERYTHING to stderr so
      // stdout stays clean for the JSON result.
      // F-008: a SYNCHRONOUS write failure is normalized and thrown to the CORE
      // guard, which flips its passthrough-broken flag: delivery stops, the run
      // still completes, and result.passthroughError surfaces the failure honestly.
      // F-020: a real EPIPE (the downstream pipe closed) usually surfaces NOT as a
      // synchronous throw but as an ASYNCHRONOUS 'error' event on process.stdout /
      // process.stderr, which the try/catch below cannot see. The 'error' listeners
      // attached for the duration of the run (below) record the first such failure
      // into `asyncStreamError`; the sink checks it and throws-through so the SAME
      // core passthrough-broken flag flips (delivery stops instead of hammering a
      // dead pipe), and the handler also merges it into the surfaced
      // passthroughError as a backstop for an error that lands after the last chunk.
      let asyncStreamError: string | null = null;
      // F-020 / F-024: track a broken STDOUT and STDERR specifically. Any chunk or
      // diagnostic write issued to a stream we already KNOW is broken would queue an
      // async EPIPE 'error' that can fire AFTER the per-call listener is removed
      // (zero listeners -> process crash). We skip those writes instead — honest
      // degradation, since passthroughError already records the failure.
      let stdoutBroken = false;
      let stderrBroken = false;

      // F-020: contain ASYNC stream 'error' events (real EPIPE) for the DURATION of
      // the run. Node terminates the process only when a stream has ZERO 'error'
      // listeners, so simply attaching ours is sufficient containment: we swallow
      // the error and record the first message. Hygiene: exactly our two named
      // listeners are added below and removed with removeListener in the finally
      // — never removeAllListeners, since other code may hold its own listeners on
      // these shared streams. F-024: a write error surfaced through a write CALLBACK
      // folds into the SAME state, so a late EPIPE reported via callback and one
      // reported via the 'error' event are handled identically.
      const recordStreamError = (streamName: 'stdout' | 'stderr') => (err: unknown): void => {
        if (streamName === 'stderr') stderrBroken = true;
        else stdoutBroken = true;
        if (asyncStreamError === null) {
          const message = err instanceof Error ? err.message : String(err);
          asyncStreamError = `host_run passthrough ${streamName} stream error: ${message}`;
        }
      };
      const onStdoutError = recordStreamError('stdout');
      const onStderrError = recordStreamError('stderr');

      // F-024: outstanding-write accounting for the live passthrough AND the final
      // diagnostics, WITHOUT serializing throughput. Every write below is issued as
      // write(text, cb) and is NOT awaited per-chunk; the callback decrements a
      // shared pending counter. drainPending() — awaited by the finally BEFORE the
      // error listeners are removed — resolves once every in-flight write has
      // settled, so a late EPIPE from the FINAL chunk(s) fires while our named
      // 'error' listeners are still attached. This closes the residual window that
      // F-020/F-023 left on fire-and-forget live passthrough writes.
      let pendingWrites = 0;
      let onDrained: (() => void) | null = null;
      const settleWrite = (): void => {
        // the handler never re-prints it (no double-print). F-023: await every
        // diagnostic write so it settles while our stderr listener is still
        // attached (finally removes it) — the crux case is this quiet-run usage
        // line being the FIRST stderr write onto an already-closed stderr.
        if (passthroughWarning) await emitStderr(passthroughWarning);
        if (result.blocked || result.exitCode !== 0 || result.timedOut) {
          // Failure / refusal: usage/refusal line to stderr, then throw so the
          // process exits nonzero (engine forces exit 0 on a normal return).
          await emitStderr(`${usageLine}\n`);
          if (result.blocked) {
            throw new Error(`host_run refused (${result.refusalReason}); no host was launched`);
          }
          const timeoutNote = result.timedOut ? ' (timed out)' : '';
          throw new Error(`host_run: ${result.host} exited ${result.exitCode}${timeoutNote}`);
        }

        // Success: output already streamed; nothing left to print. F-023: await
        // the final usage-line write so a late EPIPE fires under our listener.
        await emitStderr(`${usageLine}\n`);
        return '';
      } finally {
        // F-024: await all in-flight passthrough + diagnostic writes (bounded by the
        // defensive DRAIN_CAP_MS) BEFORE removing the error listeners, so a late
        // EPIPE from the FINAL chunk(s) fires while our named 'error' listeners are
        // still attached. Resolves immediately when nothing is pending.
        await drainPending();
        // F-020: listener hygiene — remove exactly our two listeners, leaving any
        // other listeners on these shared streams untouched.
        process.stdout.removeListener('error', onStdoutError);
        process.stderr.removeListener('error', onStderrError);
      }
    },

    async host_run_status(args: HostRunStatusCommandArgs) {
      const runId = normalizeString(args.runId);
      if (!runId) throw new Error('host_run_status: --runId is required');
      const afterGeneration = optionalNonnegativeInteger(
        'host_run_status',
        'afterGeneration',
        args.afterGeneration,
      );
      const afterSequence = optionalNonnegativeInteger('host_run_status', 'afterSequence', args.afterSequence);
      const waitMs = optionalNonnegativeInteger('host_run_status', 'waitMs', args.waitMs, 30_000);
      const status = await getManagedHostRunStatus({
        root: ctx.root,
        runId,
        afterGeneration,
        waitMs,
        maxWaitMs: options.statusWaitCapMs,
      });
      const output = readManagedHostRunOutput({
        root: ctx.root,
        runId,
        afterSequence: afterSequence ?? 0,
      });
      if (wantsJson(args)) return { ...status, output };
      const terminal = status.run.terminal
        ? ` terminal=${status.run.terminal.state}:${status.run.terminal.reason}`
        : '';
      const receipt = status.receipt ? ` receiptId=${status.receipt.receiptId}` : '';
      return `${status.run.runId} state=${status.run.state} generation=${status.run.generation} deadlineAt=${status.run.deadlineAt} workerHeartbeatAt=${status.run.workerHeartbeatAt ?? 'none'} providerProgressMode=${status.run.providerProgressMode} lastProviderProgressAt=${status.run.lastProviderProgressAt ?? 'none'} replacementSafe=${status.run.replacementSafe}${terminal}${receipt}`;
    },

    async host_run_cancel(args: HostRunCancelCommandArgs) {
      const runId = normalizeString(args.runId);
      if (!runId) throw new Error('host_run_cancel: --runId is required');
      const run = await cancelManagedHostRun({
        root: ctx.root,
        runId,
        reason: normalizeString(args.reason) || undefined,
      });
      if (wantsJson(args)) return { schemaVersion: 'lattice.host_run_cancel.v1', run };
      return `${run.runId} state=${run.state} cancelRequestedAt=${run.cancelRequestedAt ?? 'none'} replacementSafe=${run.replacementSafe}`;
    },

    async host_run_worker(args: HostRunWorkerCommandArgs): Promise<string> {
      const runId = normalizeString(args.runId);
      if (!runId) throw new Error('host_run_worker: --runId is required');
      await runManagedHostRunWorker({ root: ctx.root, runId });
      return '';
    },
  };
}
      }
    }
    child.unref();
    return { pid: child.pid };
  } finally {
    closeSync(logFd);
  }
};

export function assertManagedHostRunPlatformSupported(platform: NodeJS.Platform | string): void {
  if (platform === 'win32') {
    throw new Error('managed host run: unsupported platform win32; POSIX process-group supervision is required before provider spawn');
  }
}

export async function submitManagedHostRun(
  args: ManagedHostRunSubmitArgs,
  deps: ManagedHostRunSubmitDeps = {},
): Promise<ManagedHostRunProjection> {
  if (!args.root || !args.cwd) throw new Error('managed host run: root and cwd are required');
  if (!args.promptText) throw new Error('managed host run: prompt is empty; refuse pre-spawn');
  if (!args.phase || !args.agentType) throw new Error('managed host run: phase and agentType are required');
  const platform = deps.platform ?? process.platform;
  if (args.reviewRunId && args.storyId && !args.reviewRunId.startsWith(`${args.storyId}:`)) {
    throw new Error(`managed host run: reviewRunId "${args.reviewRunId}" does not belong to story "${args.storyId}"`);
  }
  if (args.profile === 'managed_reviewer') {
    if (!args.storyId || !args.reviewRunId || !args.lane || args.agentType !== args.lane || !args.reviewBinding) {
      throw new Error('managed host run: managed_reviewer requires exact storyId/reviewRunId/lane/agentType/reviewBinding');
    }
    const binding = args.reviewBinding;
    if (![binding.headHash, binding.materialHash, binding.storyFilesHash, binding.promptHash].every(value => value.trim().length > 0)) {
      throw new Error('managed host run: managed_reviewer reviewBinding fields must be non-empty');
    }
  }

  const now = deps.now ?? Date.now;
  const createdMs = now();
  const createdAt = new Date(createdMs).toISOString();
  const deadlineMs = boundedPositiveMs(args.deadlineMs, MANAGED_HOST_RUN_DEFAULT_DEADLINE_MS, MANAGED_HOST_RUN_MAX_DEADLINE_MS);
  const timeoutMs = boundedPositiveMs(args.timeoutMs, deadlineMs, deadlineMs);
  const deadlineAt = new Date(createdMs + deadlineMs).toISOString();
  const runId = (deps.randomId ?? randomUUID)();
  assertRunId(runId);
  const paths = pathsFor(args.root, runId);
  mkdirSync(managedHostRunsRoot(args.root), { recursive: true, mode: 0o700 });
  mkdirSync(paths.dir, { mode: 0o700 });

  const proposalInvocationKeys = args.profile === 'managed_reviewer' ? generateEd25519KeyPair() : null;
  const capability = proposalInvocationKeys?.privateKey ?? randomBytes(32).toString('base64url');
  const spec: ManagedHostRunSpec = {
    schemaVersion: MANAGED_HOST_RUN_SCHEMA_VERSION,
    runId,
    host: args.host,
    storyId: args.storyId,
    phase: args.phase,
    agentType: args.agentType,
    reviewRunId: args.reviewRunId ?? null,
    lane: args.lane ?? null,
    cwd: args.cwd,
    root: args.root,
    createdAt,
    deadlineAt,
    timeoutMs,
    agyPrintTimeout: args.agyPrintTimeout ?? null,
    projectRootHash: args.projectRootHash,
    profile: args.profile ?? null,
    reviewBinding: args.reviewBinding ?? null,
  };
  atomicWrite(paths.spec, spec);
  const owner: ManagedHostRunOwner = {
    schemaVersion: MANAGED_HOST_RUN_SCHEMA_VERSION,
    runId,
    capabilityDigest: sha256(capability),
    proposalInvocationPublicKey: proposalInvocationKeys?.publicKey ?? null,
    specDigest: sha256(readFileSync(paths.spec, 'utf8')),
    promptDigest: sha256(args.promptText),
    environmentDigest: args.environment ? sha256(canonicalJson(args.environment)) : null,
    createdAt,
  };
  atomicWrite(paths.owner, owner);
  atomicWrite(paths.snapshot, {
    schemaVersion: MANAGED_HOST_RUN_SCHEMA_VERSION,
    runId,
    state: 'submitted',
    generation: 1,
    createdAt,
    deadlineAt,
    workerPid: null,
    workerHeartbeatAt: null,
    lastProviderProgressAt: null,
    providerProgressMode: args.providerProgressMode ?? 'output-observable',
    providerLaunchState: 'pending',
    providerIdentity: null,
    outputSequence: 0,
    outputRetainedBytes: 0,
    outputTruncated: false,
    replacementSafe: false,
  } satisfies ManagedHostRunSnapshot);
  appendEvent(paths, {
    schemaVersion: MANAGED_HOST_RUN_SCHEMA_VERSION,
    runId,
    at: createdAt,
    type: 'submitted',
  });
  try {
    assertManagedHostRunPlatformSupported(platform);
  } catch {
    writeTerminal(paths, 'failed', `unsupported_platform:${platform}`, true, null, now());
    return projectionFor(paths);
  }
  // Production uses the descriptor-only worker launcher. Injected launchers are
  // an explicit test seam and may start the worker in a separate fixture
  // process, so retain the legacy one-shot file only for that seam.
  if (!proposalInvocationKeys || (deps.launchWorker && deps.workerCapabilityTransport !== 'descriptor')) {
    writeFileSync(paths.capability, capability, { encoding: 'utf8', mode: 0o600, flag: 'wx' });
  }
  writeFileSync(paths.prompt, args.promptText, { encoding: 'utf8', mode: 0o600, flag: 'wx' });
  if (args.environment) {
    writeFileSync(paths.environment, `${canonicalJson(args.environment)}\n`, { encoding: 'utf8', mode: 0o600, flag: 'wx' });
  }

  let launchedWorker: ManagedHostRunWorkerLaunchResult;
  try {
    launchedWorker = await (deps.launchWorker ?? defaultManagedHostRunWorkerLauncher)({
      root: args.root,
      runId,
      ...(proposalInvocationKeys ? { proposalInvocationPrivateKey: proposalInvocationKeys.privateKey } : {}),
    });
    updateSnapshot(paths, current => ({ ...current, workerPid: launchedWorker.pid }));
  } catch (error) {
    unlinkIfPresent(paths.capability);
    unlinkIfPresent(paths.prompt);
    unlinkIfPresent(paths.environment);
    // A launcher may throw after the OS process exists but before it can return
    // the worker pid. Without a returned identity the submitter cannot prove
    // reap or replacement safety, so publish the ambiguity honestly.
    writeTerminal(paths, 'failed', `worker_launch_failed:${error instanceof Error ? error.message : String(error)}`, false, null, now());
    return projectionFor(paths);
  }

  const claimTimeoutMs = boundedPositiveMs(deps.claimTimeoutMs, MANAGED_HOST_RUN_CLAIM_TIMEOUT_MS, MANAGED_HOST_RUN_STATUS_WAIT_MAX_MS);
  const claimPollMs = boundedPositiveMs(deps.claimPollMs, 20, 1_000);
  const claimDeadline = Date.now() + claimTimeoutMs;
  while (Date.now() < claimDeadline) {
    const terminal = readTerminal(paths);
    if (terminal) return projectionFor(paths);
    if (existsSync(paths.claim)) {
      const snapshot = readJson<ManagedHostRunSnapshot>(paths.snapshot);
      if (snapshot.state === 'running') return projectionFor(paths);
    }
    await sleep(claimPollMs);
  }

  // Serialize the final no-claim decision against the worker's durable claim.
  // Otherwise a worker blocked on one-shot input can cross this boundary after
  // the submitter has already published a conflicting failed terminal.
  return withMkdirLock(paths.claimLock, () => {
    if (readTerminal(paths) || existsSync(paths.claim)) return projectionFor(paths);
    unlinkIfPresent(paths.capability);
    unlinkIfPresent(paths.prompt);
    unlinkIfPresent(paths.environment);
    writeTerminal(paths, 'failed', 'worker_claim_timeout', !pidAlive(launchedWorker.pid), null, now());
    return projectionFor(paths);
  }, { label: `managed host run ${runId} submit/claim fence` });
}

export async function runManagedHostRunWorker(
  request: ManagedHostRunWorkerRequest,
  deps: ManagedHostRunWorkerDeps = {},
): Promise<ManagedHostRunTerminal> {
  const paths = pathsFor(request.root, request.runId);
  const existing = readTerminal(paths);
  if (existing) return existing;
  const spec = readJson<ManagedHostRunSpec>(paths.spec);
  const owner = readJson<ManagedHostRunOwner>(paths.owner);
  const proposalInvocationPrivateKey = request.proposalInvocationPrivateKey
    ?? readWorkerProposalInvocationPrivateKey(deps.env ?? process.env);
  const now = deps.now ?? Date.now;
  const claimedAt = new Date(now()).toISOString();
  const claim: ManagedHostRunClaim = {
    schemaVersion: MANAGED_HOST_RUN_SCHEMA_VERSION,
    runId: request.runId,
    workerPid: process.pid,
    claimedAt,
    capabilityDigest: owner.capabilityDigest,
  };
  const terminalBeforeClaim = withMkdirLock(paths.claimLock, () => {
    const terminal = readTerminal(paths);
    if (terminal) return terminal;
    if (!writeExclusive(paths.claim, claim)) {
      throw new Error(`managed host run ${request.runId}: already claimed`);
    }
    return null;
  }, { label: `managed host run ${request.runId} worker claim` });
  if (terminalBeforeClaim) return terminalBeforeClaim;

  // Claim ownership before opening one-shot inputs. Named pipes, slow
  // filesystems, or provider-neutral descriptor brokers may legitimately make
  // these reads slow; publish the claimed worker as running before those reads
  // so the submit response cannot contradict its durable ownership handshake.
  updateSnapshot(paths, current => ({
    ...current,
    state: 'running',
    generation: current.generation + 1,
    workerPid: process.pid,
    workerHeartbeatAt: claimedAt,
  }));
  appendEvent(paths, {
    schemaVersion: MANAGED_HOST_RUN_SCHEMA_VERSION,
    runId: request.runId,
    at: claimedAt,
    type: 'worker_claimed',
    detail: { workerPid: process.pid },
  });
  let capability: string;
  let promptText: string;
  let oneShotEnvironment: NodeJS.ProcessEnv | null;
  try {
    capability = proposalInvocationPrivateKey ?? readFileSync(paths.capability, 'utf8');
    if (sha256(capability) !== owner.capabilityDigest) {
      return writeTerminal(paths, 'failed', 'worker_capability_mismatch', true, null, now());
    }
    promptText = readFileSync(paths.prompt, 'utf8');
    if (sha256(promptText) !== owner.promptDigest) {
      return writeTerminal(paths, 'failed', 'worker_prompt_digest_mismatch', true, null, now());
    }
    oneShotEnvironment = existsSync(paths.environment)
      ? readJson<NodeJS.ProcessEnv>(paths.environment)
      : null;
    if (oneShotEnvironment && sha256(canonicalJson(oneShotEnvironment)) !== owner.environmentDigest) {
      return writeTerminal(paths, 'failed', 'worker_environment_digest_mismatch', true, null, now());
    }
  } catch (error) {
    return writeTerminal(
      paths,
      'failed',
      `worker_input_error:${error instanceof Error ? error.message : String(error)}`,
      true,
      null,
      now(),
    );
  } finally {
    unlinkIfPresent(paths.capability);
    unlinkIfPresent(paths.prompt);
    unlinkIfPresent(paths.environment);
  }

  const abort = new AbortController();
  let cancelTriggered = false;
  let deadlineTriggered = false;
  let supervisorFailure: Error | null = null;
  const failSupervisor = (error: unknown): void => {
    if (supervisorFailure === null) {
      supervisorFailure = error instanceof Error ? error : new Error(String(error));
    }
    if (!abort.signal.aborted) abort.abort(supervisorFailure);
  };
  let outputSequence = readJson<ManagedHostRunSnapshot>(paths.snapshot).outputSequence;
  let outputRetainedBytes = readJson<ManagedHostRunSnapshot>(paths.snapshot).outputRetainedBytes ?? 0;
  let outputTruncated = readJson<ManagedHostRunSnapshot>(paths.snapshot).outputTruncated ?? false;
  const heartbeatMs = boundedPositiveMs(deps.heartbeatMs, 5_000, 60_000);
  const cancelPollMs = boundedPositiveMs(deps.cancelPollMs, 100, 5_000);
  const heartbeat = setInterval(() => {
    if (readTerminal(paths)) return;
    const at = new Date(now()).toISOString();
    try {
      updateSnapshot(paths, current => ({
        ...current,
        generation: current.generation + 1,
        workerHeartbeatAt: at,
        outputSequence,
        outputRetainedBytes,
        outputTruncated,
      }));
    } catch (error) {
      // Runtime retention/test cleanup may remove the authoritative snapshot while
      // the unref'ed heartbeat is between its terminal check and locked RMW.  A
      // missing snapshot is terminal for this worker: recreating it would invent
      // state after the run authority has been removed.
      if ((error as NodeJS.ErrnoException).code === 'ENOENT' && !existsSync(paths.snapshot)) {
        clearInterval(heartbeat);
        return;
      }
      failSupervisor(error);
    }
              schemaVersion: 'lattice.managed_review_proposal_invocation.v1',
              runId: spec.runId,
              storyId: spec.storyId!,
              providerAgent: spec.agentType,
              lane: spec.lane!,
              reviewRunId: spec.reviewRunId!,
              providerIdentity: identity,
              invocationNonce: randomUUID(),
              issuedAt: new Date(now()).toISOString(),
              expiresAt: new Date(now() + 120_000).toISOString(),
            }, proposalInvocationPrivateKey as PrivateKeyBase64)),
          }
          : {}),
        passthrough: chunk => {
          withTerminalAuthorityLock(paths, () => {
            if (readTerminal(paths)) return;
            outputSequence += 1;
            const progressAt = new Date(now()).toISOString();
            const frame: ManagedHostRunOutputFrame = {
              sequence: outputSequence,
              at: progressAt,
              stream: chunk.stream,
              text: chunk.text,
            };
            const encoded = `${canonicalJson(frame)}\n`;
            const encodedBytes = Buffer.byteLength(encoded, 'utf8');
            if (outputRetainedBytes + encodedBytes <= MANAGED_HOST_RUN_OUTPUT_RETENTION_MAX_BYTES) {
              appendFileSync(paths.output, encoded, { encoding: 'utf8', mode: 0o600 });
              outputRetainedBytes += encodedBytes;
            } else {
              outputTruncated = true;
            }
            updateSnapshotUnlocked(paths, current => ({
              ...current,
              generation: current.generation + 1,
              outputSequence,
              outputRetainedBytes,
              outputTruncated,
              lastProviderProgressAt: progressAt,
            }));
