   * both are accepted by checkDispatchPolicy. REQUIRED: the handler fails closed
   * (no codex spawn) when it is missing or unauthorized.
   */
  policy?: string | DispatchPolicy;
  hostAFindingsFile?: string;
  hostA?: string;
